"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["80583"],{3733(e){e.exports=JSON.parse('{"id":"F408","slug":"cir-moments-feller","name":"Cox-Ingersoll-Ross Moments and Feller Condition","subject":"Quantitative Finance","section":"Quant","topic":"Interest rate models (Vasicek, CIR, Hull-White)","level":"Intermediate","aliases":["CIR model","square root process","Feller condition","non-negative interest rates"],"formula":{"latex":"E[r_{t}]=\\\\theta+(r_{0}-\\\\theta)e^{-\\\\kappa t},\\\\quad 2\\\\kappa\\\\theta\\\\ge\\\\sigma^{2}","also":[],"text":"Expected rate = theta + (r0 - theta) x e^(-kappa t); Variance = r0 x sigma^2 / kappa x (e^(-kappa t) - e^(-2 kappa t)) + theta x sigma^2 / (2 kappa) x (1 - e^(-kappa t))^2; the rate stays above zero if 2 x kappa x theta >= sigma^2"},"symbols":[{"symbol":"r_0","meaning":"Current rate","unit":"per year"},{"symbol":"theta","meaning":"Long-run mean","unit":"per year"},{"symbol":"kappa","meaning":"Speed of reversion","unit":"per year"},{"symbol":"sigma","meaning":"Volatility parameter. Shocks scale with sqrt(r), so volatility falls as the rate falls","unit":"number"}],"when_to_use":"Use it for a mean-reverting rate that cannot go negative. Shocks shrink as the rate nears zero, which keeps it positive when the Feller condition holds. If the condition fails, the rate can touch zero (it still never goes below). The same process is used for variance in the Heston model.","worked_example":{"problem":"The rate is 3%, the long-run mean is 5%, the speed is 0.8 and sigma is 0.10. Find the mean and standard deviation of the rate in 2 years and test the Feller condition.","inputs":{"r0":3,"th":5,"k":0.8,"sg":0.1,"t":2},"steps":[{"label":"Expected rate = theta + (r0 - theta) e^(-kappa t)","working":"0.05+(0.03-0.05) x exp(-0.8 x 2)","value":"4.596%"},{"label":"Variance","working":"0.03 x 0.1^2 / 0.8 x (exp(-0.8 x 2)-exp(-2 x 0.8 x 2))+0.05 x 0.1^2 / (2 x 0.8) x (1-exp(-0.8 x 2))^2","value":"0.00025948"},{"label":"Standard deviation","working":"sqrt(var)","value":"1.611%"},{"label":"2 x kappa x theta","working":"2 x 0.8 x 0.05","value":"0.0800"},{"label":"sigma squared","working":"0.1^2","value":"0.0100"},{"label":"Feller condition holds? (1 = yes, 0 = no)","working":"1 if 0.08>=0.01 else 0","value":"1"}],"answer":"In 2 years the expected rate is 4.596% with a standard deviation of 1.611%. The Feller test compares 2 kappa theta = 0.0800 with sigma squared = 0.0100. The condition holds, so the rate stays positive."},"calculator":{"available":true,"inputs":[{"id":"r0","label":"Current rate","unit":"%","type":"number","default":3,"hint":""},{"id":"th","label":"Long-run mean","unit":"%","type":"number","default":5,"hint":""},{"id":"k","label":"Speed of reversion","unit":"","type":"number","default":0.8,"hint":""},{"id":"sg","label":"Sigma","unit":"","type":"number","default":0.1,"hint":""},{"id":"t","label":"Years","unit":"years","type":"number","default":2,"hint":"","min":0.1}],"checks":[{"expr":"k>0 and sg>=0","message":"The speed must be above zero and sigma not negative."}],"steps":[{"id":"mean","label":"Expected rate = theta + (r0 - theta) e^(-kappa t)","expr":"th+(r0-th)*exp(-k*t)","format":"pct3"},{"id":"var","label":"Variance","expr":"r0*sg^2/k*(exp(-k*t)-exp(-2*k*t))+th*sg^2/(2*k)*(1-exp(-k*t))^2","format":"num8"},{"id":"sd","label":"Standard deviation","expr":"sqrt(var)","format":"pct3"},{"id":"lhs","label":"2 x kappa x theta","expr":"2*k*th","format":"num4"},{"id":"rhs","label":"sigma squared","expr":"sg^2","format":"num4"},{"id":"ok","label":"Feller condition holds? (1 = yes, 0 = no)","expr":"1 if lhs>=rhs else 0","format":"num0"}],"results":["mean","sd","ok"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"mean":0.04596206964010689,"var":2.5947823275268827e-4,"sd":0.01610832805578184,"lhs":0.08,"rhs":0.01,"ok":1}},"finder":{"finds":"Where a square-root rate is expected to be and whether it stays positive","needs":"Rate, long-run mean, speed, sigma, time"},"related":[{"slug":"vasicek-zero-bond","name":"Vasicek Model Zero-Coupon Bond Price"},{"slug":"ou-process-moments","name":"Mean-Reverting (Ornstein-Uhlenbeck) Process Moments"},{"slug":"heston-variance","name":"Heston Model: Average Variance and Feller Condition"}],"related_ids":["F409","F399","F410"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>E</mi><mo stretchy=\\"false\\">[</mo><msub><mi>r</mi><mi>t</mi></msub><mo stretchy=\\"false\\">]</mo><mo>=</mo><mi>\u03B8</mi><mo>+</mo><mo stretchy=\\"false\\">(</mo><msub><mi>r</mi><mn>0</mn></msub><mo>\u2212</mo><mi>\u03B8</mi><mo stretchy=\\"false\\">)</mo><msup><mi>e</mi><mrow><mo>\u2212</mo><mi>\u03BA</mi><mi>t</mi></mrow></msup><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mn>2</mn><mi>\u03BA</mi><mi>\u03B8</mi><mo>\u2265</mo><msup><mi>\u03C3</mi><mn>2</mn></msup></mrow><annotation encoding=\\"application/x-tex\\">E[r_{t}]=\\\\theta+(r_{0}-\\\\theta)e^{-\\\\kappa t},\\\\quad 2\\\\kappa\\\\theta\\\\ge\\\\sigma^{2}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"covered-interest-arbitrage","name":"Covered Interest Parity and Arbitrage"},"next":{"slug":"credit-card-payoff","name":"Credit Card Payoff Time and Interest"},"lesson":null,"total":522}')}}]);